    /**
     * 发送http请求
     * @param handler 请求回调；
     * @param action 方法
     * @param srvArgs 参数；
     */
    public static requestGet(action: string, srvArgs?: any, needErrorCode = false): any {
        return new Promise((resolve, reject) => {
            var xhr: HttpRequest = Laya.Pool.getItem("HttpRequest");
            if (!xhr) {
                xhr = new HttpRequest();
            }
            xhr.http.timeout = 6000; //设置超时时间；
            xhr.on(Laya.Event.COMPLETE, null, completeHandler);
            xhr.on(Laya.Event.ERROR, null, errorHandler);
            xhr.http.onreadystatechange = () => {
                // In local files, status is 0 upon success in Mozilla Firefox
                if (xhr.http.readyState === XMLHttpRequest.DONE) {
                    var status = xhr.http.status;
                    if (status >= 200 && status < 400) {
                    } else {
                        reject();
                        recover();
                    }
                }
            };

            let token = localStorage.getItem("TOX-COOKIE" + EthereumManager.walletAddress);
            let header = ["Content-Type", "application/json"];
            if (token) {
                header = [...header, ...["Authorization", token]];
            }

            let realUrl;
            //数据拼接
            if (action.startsWith("http")) {
                realUrl = action + parseArgs(srvArgs);
                // xhr.send(action, srvArgs,"post",'json',header);
            } else {
                realUrl = HttpCmd.httpRoot + "/" + action + parseArgs(srvArgs);
            }

            // //数据拼接
            // let realUrl = HttpCmd.httpRoot+ "/" + action+parseArgs(srvArgs);
            if (HttpCmd.httpRoot != "https://api.phantomarena.co") {
                console.log("REQUEST_GET " + realUrl, 1);
            }
            xhr.send(realUrl, null, "get", "json", header);

            function parseArgs(args: any): string {
                if (typeof args === "string") {
                    return args;
                }
                let str = "";
                for (let i in args) {
                    str += "&" + i + "=" + args[i];
                }
                return str;
            }

            function completeHandler(data: any): void {
                if (needErrorCode) {
                    if (data.code === "0") {
                        resolve(data.data);
                    } else {
                        NoticeMgr.notice(GameLanguageMgr.getError(data.code));
                        // ErrorPopManager.showErrorWord(parseInt(data.code));
                        reject(data.code);
                    }
                } else {
                    resolve(data);
                }

                recover();
            }

            function errorHandler(data: Object, e: Event): void {
                // debugger;
                //需要一些特殊的处理
                reject(data);
                recover();
            }

            function recover(): void {
                xhr.off(Laya.Event.COMPLETE, null, completeHandler);
                xhr.off(Laya.Event.ERROR, null, errorHandler);
                Laya.Pool.recover("HttpRequest", xhr);
            }
        });
    }

