    public static startHeart() {
        //帧听舞台事件，当失去焦点后，停止每帧更新
        Laya.stage.on(Laya.Event.BLUR, this, () => {
            this.stopHeartInStage = true;
            console.log("失去焦点, 停止心跳");
        });
        //当恢复鼠标焦点后，恢复每帧更新
        Laya.stage.on(Laya.Event.FOCUS, this, () => {
            this.stopHeartInStage = false;
            console.log("获取焦点, 开始心跳");
        });
        // if(GameSetting.Debug != 2)
        Laya.timer.loop(3000, this, this.onHeart);
    }
