    /**
     * ping测试函数，测量与服务器连接建立的延迟时间
     * @param url 服务器地址，例如：https://wss-room-sg.candyhouse.vip/test-ping
     * @returns Promise<number> 返回连接建立的延迟时间（毫秒）
     */
    public static async pingServer(url: string): Promise<number> {
        return new Promise((resolve) => {
            if (!url) {
                // console.error("URL不能为空");
                resolve(9999);
                return;
            }

            // 如果URL以@开头，移除@符号
            if (url.startsWith("@")) {
                url = url.substring(1);
            }

            // console.log(`开始ping服务器: ${url}`);

            // 清理URL，移除查询参数
            let baseUrl = url;
            if (baseUrl.includes("?")) {
                baseUrl = baseUrl.split("?")[0];
            }

            // 创建专用于测量TCP连接时间的方法
            const testConnection = () => {
                const startTime = Date.now();
                let isDone = false;

                // 创建新的XMLHttpRequest对象
                const xhr = new XMLHttpRequest();

                // 连接建立事件 - 关键是检测到状态变化
                xhr.onreadystatechange = function () {
                    // 只检查连接建立，不关心完成状态
                    if (!isDone && xhr.readyState >= 1 && xhr.readyState < 4) {
                        const connectionTime = Date.now() - startTime;
                        if (connectionTime > 0) {
                            // 确保延迟时间 > 0
                            isDone = true;
                            // console.log(`连接建立成功，延迟：${connectionTime}ms, readyState: ${xhr.readyState}`);
                            resolve(connectionTime);
                        }
                    }
                };

                // 加载完成事件 - 如果onreadystatechange没有触发计时
                xhr.onload = function () {
                    if (!isDone) {
                        const connectionTime = Date.now() - startTime;
                        isDone = true;
                        // console.log(`请求完成，延迟：${connectionTime}ms`);
                        resolve(connectionTime > 0 ? connectionTime : 1); // 确保至少返回1ms
                    }
                };

                // 错误处理
                xhr.onerror = function (e) {
                    if (!isDone) {
                        const connectionTime = Date.now() - startTime;
                        isDone = true;
                        // console.log(`连接出错但已建立连接，延迟：${connectionTime}ms`);
                        resolve(connectionTime > 0 ? connectionTime : 500); // 给一个合理的估计值
                    }
                };

                // 超时处理
                xhr.timeout = 5000;
                xhr.ontimeout = function () {
                    if (!isDone) {
                        isDone = true;
                        // console.log("连接超时");
                        resolve(5000); // 超时时返回超时时间
                    }
                };

                try {
                    // 关键：避免CORS问题的同时测量TCP连接时间

                    // 为URL添加随机参数避免缓存
                    const timestamp = Date.now();
                    const randomNum = Math.floor(Math.random() * 10000);
                    const pingUrl = `${baseUrl}?_t=${timestamp}&r=${randomNum}`;

                    // 使用GET方法，设置最小超时，并启动计时
                    xhr.open("GET", pingUrl, true);

                    // 请求开始前的额外延迟，确保时间计算准确
                    setTimeout(() => {
                        try {
                            xhr.send();
                        } catch (e) {
                            if (!isDone) {
                                isDone = true;
                                // console.log("发送请求时出错");
                                resolve(9999);
                            }
                        }
                    }, 10);
                } catch (e) {
                    if (!isDone) {
                        isDone = true;
                        // console.log("创建请求时出错");
                        resolve(9999);
                    }
                }

                // 设置最终超时保障
                setTimeout(() => {
                    if (!isDone) {
                        isDone = true;
                        // console.log("最终超时保护触发");
                        resolve(9999);
                    }
                }, 5500);
            };

            // 尝试使用图片加载方式（更少CORS问题）
            const imgTest = () => {
                const startTime = Date.now();
                let isDone = false;

                // 创建图像对象
                const img = new Image();

                // 加载完成事件
                img.onload = function () {
                    if (!isDone) {
                        const loadTime = Date.now() - startTime;
                        isDone = true;
                        // console.log(`图片加载成功，延迟：${loadTime}ms`);
                        resolve(loadTime > 0 ? loadTime : 1);
                    }
                };

                // 错误处理
                img.onerror = function () {
                    if (!isDone) {
                        const connTime = Date.now() - startTime;
                        isDone = true;
                        // console.log(`图片加载失败，但连接已建立，延迟：${connTime}ms`);

                        // 图片加载失败但连接可能已建立，尝试XMLHttpRequest方法
                        if (connTime > 0) {
                            resolve(connTime);
                        } else {
                            testConnection();
                        }
                    }
                };

                // 设置超时
                setTimeout(() => {
                    if (!isDone) {
                        isDone = true;
                        // console.log("图片加载超时，尝试XMLHttpRequest方法");
                        testConnection();
                    }
                }, 3000);

                // 设置随机参数避免缓存
                const timestamp = Date.now();
                const random = Math.floor(Math.random() * 10000);
                const imgUrl = `${baseUrl}?_t=${timestamp}&r=${random}&type=image`;

                // 开始加载图片
                img.src = imgUrl;
            };

            // 先尝试图片加载方式，如果失败再尝试XMLHttpRequest
            imgTest();
        });
    }
