import { BaseItem } from "./BaseItem";

export class RoomItem extends BaseItem {
    public roomType: number; //网络
    public id: number; //序号
    public ticketType: number[]; //门票类型
    public ticketAmount: number[]; //门票金额
    public team: number; //支持团战
    public level: number; //等级要求
    public count: number; //启动房间数
    public minTicketAmount: number[]; //最小门票金额
}
