const { regClass } = Laya;
import AssetManager from "../../manager/AssetManager";
import { TimeUtil } from "../../utils/TimeUtil";
import { ClubRoomListItemBase } from "./ClubRoomListItem.generated";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import Signal from "../../global/event/Signal";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import EnterRoomManager from "../hall/EnterRoomManager";
import { ClubRoomList } from "./ClubRoomList";
import ClubManager from "../../global/ClubManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import { RoomVo } from "../../data/vo/pack/RoomVo";
import { EnumMatch } from "../../data/enumData/EnumMatch";

@regClass('euaIDdILQNabNW0qaF17nA==')
export class ClubRoomListItem extends ClubRoomListItemBase {
    public constructor() {
        super();
    }

    public referralData: any; // 改为public以便外部访问

    /** 当前展开状态 */
    isExpanded: boolean = false;
    /** 动画持续时间(ms) */
    private animDuration: number = 50;
    private headerHeight: number = 85;
    private targetHeight: number = 85;

    /** 创建内容区域 */
    private createContent(): void {
        this.content.alpha = this.isExpanded ? 1 : 0; // 初始化时根据状态设置alpha
    }

    /** 切换展开/折叠状态 */
    public toggle(): void {
        this.isExpanded ? this.collapse() : this.expand();
    }

    /** 展开项目 */
    public expand(): void {
        if (this.isExpanded) return;

        this.isExpanded = true;
        this.img_arrow.rotation = 90;

        // 执行展开动画
        Laya.Tween.to(this.content, { alpha: 1 }, this.animDuration);

        this.height = this.headerHeight + this.targetHeight;
    }

    /** 折叠项目 */
    public collapse(): void {
        if (!this.isExpanded) return;

        this.isExpanded = false;
        this.img_arrow.rotation = 0;

        // 执行折叠动画
        Laya.Tween.to(this.content, { alpha: 0 }, this.animDuration);

        this.height = this.headerHeight;
    }

    /** 刷新布局 */
    private refreshLayout(): void {
        if (this.content) {
            // 立即设置内容区域状态，不等待动画
            this.content.alpha = this.isExpanded ? 1 : 0;
            this.height = this.isExpanded ? this.headerHeight + this.targetHeight : this.headerHeight;
            let getClubData = ClubManager.getClubData();
            if (getClubData) {
                this.btnCloseRoom.disabled = getClubData.createrId !== GlobalDataManager.playerDto.pid;
            } else {
                this.btnCloseRoom.disabled = false;
            }
            console.log(getClubData);
        }
    }

    onEnable(): void {
        this.btnJoinRoom.on(Laya.Event.CLICK, this, this.onItemClick);
        this.btnCloseRoom.on(Laya.Event.CLICK, this, this.onCloseRoomClick);
        this.btnWatch.on(Laya.Event.CLICK, this, this.onWatchMatch);
        this.header.on(Laya.Event.CLICK, this, this.toggle);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_DELETE_CLUB_ROOM, this, this.onCloseRoomResponse);
    }

    /**
     * 观战按钮点击事件
     */
    private onWatchMatch(): void {
        if (!this.referralData) return;
        const roomNo = this.referralData.id;
        EnterRoomManager.watchPvpArenaScene(EnumMatch.ROOM_ID_JULEBU, roomNo);
    }

    onDisable(): void {
        this.btnJoinRoom.off(Laya.Event.CLICK, this, this.onItemClick);
        this.btnCloseRoom.off(Laya.Event.CLICK, this, this.onCloseRoomClick);
        this.header.off(Laya.Event.CLICK, this, this.toggle);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_DELETE_CLUB_ROOM, this, this.onCloseRoomResponse);
    }

    /**
     * 点击房间列表项时打开加入房间对话框
     */
    private onItemClick(): void {
        if (this.referralData) {
            var roomVo: RoomVo = new RoomVo();
            roomVo.id = this.referralData.id;

            roomVo.endTime = this.referralData.endTime;
            roomVo.symbolId = this.referralData.symbolId;
            roomVo.cost = this.referralData.cost;

            roomVo.map = this.referralData.map;
            roomVo.fruit = this.referralData.fruit;
            roomVo.bgm = this.referralData.bgm;
            roomVo.arenaType = EnumMatch.ARENA_TYPE_JULEBU; //俱乐部模式
            ModuleManager.intance.openModule(ModuleName.JoinClubRoomDialog, roomVo);
        }
    }

    public set dataSource(value: any) {
        if (!value) return;
        let data = value.split(",");
        super.dataSource = value;

        // 保存之前的房间ID和展开状态
        const prevRoomId = this.referralData?.id;
        const wasExpanded = this.isExpanded;

        this.referralData = {
            id: data[0],
            endTime: data[1],
            symbolId: data[2],
            cost: data[3],
            map: data[4],
            fruit: data[5],
            bgm: data[6],
            playerNum: data[7]
        };

        this.tf_roomId.text = this.referralData.id;

        const index = (this.parent as ClubRoomList)?.items?.indexOf(this) ?? 0;
        this.img_bg.visible = index % 2 === 1;

        this.updateEndTimeDisplay();

        let tokenData = AssetManager.getTokenDataBySyId(Number(this.referralData.symbolId));
        if (tokenData) {
            this.tf_tickets.text = `${parseFloat(this.referralData.cost)} ${tokenData.symbol}`;
        } else {
            this.tf_tickets.text = `${parseFloat(this.referralData.cost)}`;
        }
        this.tf_playerNum.text = `${data[7]}/${30}`;
        var playerNum = parseInt(data[7]);
        this.btnWatch.disabled = playerNum <= 0;
        if (playerNum > 0) {
            this.btnCloseRoom.disabled = true;
        }

        this.createContent();

        // 关键修复：如果是同一个房间，保持内容区域状态
        if (prevRoomId === this.referralData.id) {
            // 立即设置内容区域状态，不等待动画
            this.content.alpha = this.isExpanded ? 1 : 0;
            this.height = this.isExpanded ? this.headerHeight + this.targetHeight : this.headerHeight;

            // 更新箭头方向
            this.img_arrow.rotation = this.isExpanded ? 90 : 0;
        } else {
            // 新房间：恢复之前的展开状态
            this.isExpanded = wasExpanded;
            this.refreshLayout();
            this.img_arrow.rotation = this.isExpanded ? 90 : 0;
        }
    }

    /**
     * 更新倒计时显示
     */
    public updateEndTimeDisplay(): void {
        if (this.referralData && this.referralData.endTime) {
            this.tf_endTime.text = TimeUtil.getRestTime(Math.floor(this.referralData.endTime / 1000));
        }
    }

    /**
     * 关闭房间
     */
    private onCloseRoomClick(event: Laya.Event): void {
        event.stopPropagation();
        const cmdId = com.snake.socket.MessageType.MSG_DELETE_CLUB_ROOM;

        if (this.referralData && this.referralData.id) {
            const requestData = com.snake.socket.CS_DELETE_CLUB_ROOM.fromObject({
                roomNo: this.referralData.id
            });
            // Signal.on("msg_" + com.snake.socket.MessageType.MSG_DELETE_CLUB_ROOM, this, this.onCloseRoomResponse);
            HallWebSocket.send(cmdId, requestData);
        }
    }

    /**
     * 处理关闭房间的响应
     */
    private onCloseRoomResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.CS_DELETE_CLUB_ROOM = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.CS_DELETE_CLUB_ROOM);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            if (msgBody && msgBody.roomNo) {
                if (msgBody.roomNo) {
                    const cmdId = com.snake.socket.MessageType.MSG_CLUB_ROOM;
                    HallWebSocket.send(cmdId);
                }
            }
        }
    }
}
