        public set dataSource(value: any) {
            console.log("=========");
            super.dataSource = value;
    
            if (!value) {
                return;
            }
            this.useType = value[0];
            if (this.useType == 1) {
                this.btn_transfer.label = GameLanguageMgr.getUILang("Transfer");
            } else if (this.useType == 2) {
                this.btn_transfer.label = GameLanguageMgr.getUILang("Combine");
            } else if (this.useType == 3) {
                this.btn_transfer.label = GameLanguageMgr.getUILang("Rising star");
            } else if (this.useType == 4) {
                this.btn_transfer.label = GameLanguageMgr.getUILang("Use"); //使用
            } else if (this.useType == 6) {
                this.btn_transfer.label = GameLanguageMgr.getUILang("To Chain"); //上链
            }
            this.itemVo = value[1];
            var disabledBtn = value[2];
            this.btn_transfer.disabled = disabledBtn;
            this.addEvent();
        }
    
