const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { PlayerDto } from "../../data/dto/PlayerDto";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { ReferralRecordDialogBase } from "./ReferralRecordDialog.generated";

@regClass('nzsLXz0HRzWxxKuo+nEndg==')
export class ReferralRecordDialog extends ReferralRecordDialogBase {
       public m_strName: string = "我是OpenSceneRuntime";
        public m_iLayerType: number = LayerManager.M_POP;
        public m_iPositionType: number = LayerManager.CENTER;
        
        // 添加分页变量
        private currentPage: number = 1; // 当前页码
        private isLoading: boolean = false; // 是否正在加载数据
        private hasMoreData: boolean = true; // 是否还有更多数据
        private pageSize: number = 20; // 每页数据数量
        private inviteTotal: number = 0; // 邀请总数
        
        public constructor(_data: any) {
            super();
        }
    
        onEnable(): void {
            this.list_rental.visible = false;
            Signal.on("msg_" + com.snake.socket.MessageType.MSG_INVITE_LIST, this, this.onRequestInfo);
            
            // 添加列表滚动监听     
            this.list_rental.scrollBar.on(Laya.Event.END, this, this.onScrollEnd);
            
            // 重置分页变量
            this.currentPage = 1;
            this.isLoading = false;
            this.hasMoreData = true;
            
            // 初始化数据
            this.initContainer();
        }
    
        private initContainer(): void {
            if (this.isLoading || !this.hasMoreData) return;
            
            this.isLoading = true;
            
            //获取邀请人信息逻辑
            let playerDto: PlayerDto = GlobalDataManager.playerDto;
            var cmdId = com.snake.socket.MessageType.MSG_INVITE_LIST;
            
            // 使用分页参数
            var o = com.snake.socket.CS_INVITE_LIST.fromObject({
                pageNo: this.currentPage,
                pageSize: this.pageSize
            });
            
            HallWebSocket.send(cmdId, o);
        }
        
        /**
         * 滚动到底部时加载更多数据
         */
        private onScrollEnd(): void {
            // 判断是否滚动到底部
            var scrollBar = this.list_rental.scrollBar;
            if (scrollBar.value >= scrollBar.max - scrollBar.height) {
                if (this.hasMoreData && !this.isLoading) {
                    this.currentPage++;
                    this.initContainer();
                }
            }
        }
    
        /**
         * 获取邀请列表
         */
        public onRequestInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
            this.isLoading = false;
            
            var msgBody: com.snake.socket.SC_INVITE_LIST = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_INVITE_LIST);
            if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
                //邀请人列表数据
                var inviteList = msgBody.info;
                this.inviteTotal = msgBody.inviteCount || 0;
                
                // 如果是第一页，直接赋值；否则，追加数据
                if (this.currentPage == 1) {
                    this.list_rental.array = inviteList;
                } else {
                    // 追加数据
                    var currentData = this.list_rental.array || [];
                    this.list_rental.array = currentData.concat(inviteList);
                }
                
                this.list_rental.visible = true;
                var listData = this.list_rental.array;
                if (!listData || listData.length === 0) {
                    this.noDataBox.visible = true;
                } else {
                    this.noDataBox.visible = false;
                }
                
                // 判断是否还有更多数据
                this.hasMoreData = (this.list_rental.array.length < this.inviteTotal);
            }
        }
    
        onDisable(): void {
            Signal.off("msg_" + com.snake.socket.MessageType.MSG_INVITE_LIST, this, this.onRequestInfo);
            // 移除滚动监听
            if (this.list_rental && this.list_rental.scrollBar) {
                this.list_rental.scrollBar.off(Laya.Event.END, this, this.onScrollEnd);
            }
        }
}