import SnakeManager from "../snake/SnakeManager";
import FoodManager from "../food/FoodManager";
import MatchModel from "../../modules/match/MatchModel";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import GameAiControl from "./GameAiControl";
import AiSnakeManager from "../snake/AiSnakeManager";
import { MathUtil } from "../../utils/MathUtil";
import { Vec2 } from "../../utils/Vec2";
import { Quick } from "../../utils/Quick";
import EnterRoomManager from "../../modules/hall/EnterRoomManager";
import GameSetting from "../../global/GameSetting";

class FrameAiManager {
    private static _instance: FrameAiManager;
    public static getInstance(): FrameAiManager {
        if (!FrameAiManager._instance) {
            FrameAiManager._instance = new FrameAiManager();
        }
        return FrameAiManager._instance;
    }

    private _frameInterval: number = 33;

    /**
     * 客户端帧(可自增)
     */
    private _currentFrame: number = 0;

    isStart: boolean = false;

    private init(): void {
        this.stop();
        this.isStart = true;

        this._currentFrame = 0;
        this.lastSelfX = -1;
        this.lastSelfY = -1;
        this.samePosFrameCount = 0;
    }

    public start(): void {
        this.init();
        Laya.timer.loop(this._frameInterval, this, this.update);
    }

    private stop(): void {
        Laya.timer.clear(this, this.update);
    }
    public end(): void {
        this.stop();
        this.isStart = false;
    }

    private update(): void {
        this._currentFrame++;
        this.executeFrame(this._currentFrame);
    }

    private lastSelfX: number = -1;
    private lastSelfY: number = -1;
    private samePosFrameCount: number = 0;

    // 执行指定帧的逻辑
    private executeFrame(frame: number, hasConfirmed: boolean = true): void {
        var selfSnake = SnakeManager.getInstance().selfSnake;
        //TODO:: 暂时增加这个isStop()，防止日志太多；
        if (selfSnake && selfSnake.tag == null) {
            return;
        }
        var newHeadPos = selfSnake.getHeadPosition(false);
        var distance = MathUtil.getVecDistance(newHeadPos, Vec2.create(this.lastSelfX, this.lastSelfY));

        //用于异常退出 begin
        if (distance == 0) {
            this.samePosFrameCount++;
            if (this.samePosFrameCount > 300) {
                console.log("异常退出 同样的位置大于10秒");
                this.end();
                Quick.popToMain(2001, false, "~");
                return;
            }
        } else {
            this.samePosFrameCount = 0;
        }
        this.lastSelfX = newHeadPos.x;
        this.lastSelfY = newHeadPos.y;

        // 3. 更新所有蛇的逻辑
        GameAiControl.update(frame, false, hasConfirmed);

        FoodManager.update(Laya.timer.delta);
        (SnakeManager.getInstance() as AiSnakeManager).update(Laya.timer.delta);
    }

    public get currentFrame(): number {
        return this._currentFrame;
    }

    //============================
    sendAiEnter(): void {
        if(GameSetting.isTest){
            EnterRoomManager.goAiArenaSceneBack();
        }else{
            var cmdId = com.snake.socket.MessageType.MSG_GAME_AI_ENTER; //进入AI场
            HallWebSocket.send(cmdId, null);
        }        
    }

    sendAiEnd(count: number, isWin: boolean, score:number): void {
        var cmdId = com.snake.socket.MessageType.MSG_GAME_AI_END; //AI场结算
        var o = com.snake.socket.CS_GAME_AI_END.fromObject({
            gameId: GameSetting.gameId,
            cont: count,
            res: isWin,
            socre: score
        });
        HallWebSocket.send(cmdId, o);
        // RoomWebSocket.sendData(cmdId, o, false);
    }

    onPveEnd(isWin: boolean = true, score: number = 100) {
        var msgEndBody = new com.snake.socket.SC_GAME_RES();

        msgEndBody.res = isWin;
        msgEndBody.score = score;

        // msgEndBody.alive = MatchModel.matchCoolDownTime;

        msgEndBody.items = [];
        console.log("onPveEnd", msgEndBody);
        MatchModel.onAiSetMatchEnd(msgEndBody);
    }
}
export default FrameAiManager.getInstance();
