    /**
     * 显示样式
     * @param data
     */
    public setOpenData(data: TokenData) {
        // this.tf_adress.text = ComUtil.shortenString(EthereumManager.walletAddress, 6, 4);
        this.data = data;
        this.img_icon.skin = GameResourceManager.getCurrencyIcon(data.symbol);
        // this.tf_token.text = data.symbol;
        this.alertTitle.text = GameLanguageMgr.getLanguage(88, data.symbol);
        // console.log("data", data);
        this.requestChargeInfo();
    }

    /**
     * 请求资产信息
     */
    private requestChargeInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_CHARGE;
        const symbol = this.data.symbol;
        const requestData = com.snake.socket.CS_CHARGE.fromObject({
            symbol: symbol
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 获取充值信息
     */
    public onRequestChargeInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CHARGE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CHARGE);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("SC_CHARGE", msgBody);
            //获取到充值信息
            // this.rechargeData = msgBody;
            // let depositData = JSON.parse(msgBody);
            let data = ComUtil.parseJsonArray(msgBody.chargeInfo);
            let tonConnectUI = EthereumManager.tonConnectUI;
            console.log("tonConnectUI", tonConnectUI);
            if (!tonConnectUI && !GlobalDataManager.tonTest && !EthereumManager.isTronLogin) {
                this.setDepositData(data);
            } else if (EthereumManager.isTronLogin) {
                this.setDepositDataTron(data);
            } else {
                this.setDepositData2(data);
            }
        }
    }

    /**
     * 展示充值页面的信息2
     * @returns
     */
    private async setDepositData(data: any[]) {
        const currentChainId = await EthereumManager.walletClient.getChainId();

        // 从data数组中筛选出chainId和currentChainId相等的项目
        const matchedItem = data.find((item) => Number(item.chainId) === Number(currentChainId));
        this.realTokenData = matchedItem;
        this.img_icon.skin = GameResourceManager.getChainIcon(this.realTokenData.chainId);
        if (!matchedItem) {
            console.log("未找到匹配的链信息");
            return;
        }
        console.log(matchedItem);

        this.tf_web.text = matchedItem.chainName;
        // this.tf_token.text = matchedItem.symbol;
        // let tokenBalance = await EthereumManager.getBalance2(matchedItem.tokenAddress);
        let tokenBalance = await EthereumManager.getBalance2(matchedItem.tokenAddress);

        const decimals = matchedItem.decimals;
        let chainData = getChainInfoById(matchedItem.chainId);
        if (chainData) {
            this.yf_balanceText.text = GameLanguageMgr.getLanguage(90, chainData.symbol);

            let gasRest = await EthereumManager.getBalance2(EthereumConfig.ADDRESS0);
            const decimalsMain = chainData.decimals;
            //获取到货币的精度
            let balanceAsEther = formatUnits(gasRest, decimalsMain);
            balanceAsEther = Number(balanceAsEther)
                .toFixed(5)
                .replace(/\.?0+$/, "");
            // this.restValue = balanceAsEther;
            this.tf_mainRest.text = `${balanceAsEther} ${chainData.symbol}`;
        }
        // this.rechargeCode.prompt = GameLanguageMgr.getLanguage(87, 0.1, this.realTokenData.symbol);
        //获取到货币的精度
        let balanceAsEther = formatUnits(tokenBalance, decimals);
        // balanceAsEther = "1000000"
        // const balanceAsEtherFixed = Number(balanceAsEther).toFixed(5);
        const balanceAsEtherFixed = cutFixed(balanceAsEther, 5)
            .replace(/(\.\d*?)0+$/, "$1")
            .replace(/\.$/, "");

        this.restValue = balanceAsEtherFixed;

        this.tf_rest.text = `${balanceAsEtherFixed} ${matchedItem.symbol}`;
        this.balance = Number(balanceAsEtherFixed);

        // console.log("tokenBalance", tokenBalance);
    }

