const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import { AssetNewScene } from "./AssetNewScene";
import { AssetRecordDialogBase } from "./AssetRecordDialog.generated";

@regClass('y0xiZs+qSDWRAXN/oE10yg==')
export class AssetRecordDialog extends AssetRecordDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;

    private m_currentTabIndex: number = 2; //当前选中的tab索引
    static isDepositRecord: boolean = true; // 标记当前是充值还是提现记录
    // 资产变更记录相关变量
    private assetChangeData: any[] = [];
    private isLoadingAssetChange: boolean = false;
    private hasMoreAssetChange: boolean = true;
    private assetChangePageSize: number = 15;
    private dayIndex: number = 0;
    private sevendDayInfoDisplay: any[];

    public constructor() {
        super();
    }

    onEnable(): void {
        this.initDate();
        this.onTabClick(this.m_currentTabIndex, true);
        this.Box_time.on(Laya.Event.CLICK, this, this.showTimePanel);
        for (let i = 0; i < 3; i++) {
            (this as any)["tab" + i].on(Laya.Event.CLICK, this, this.onTabClick, [i, false]);
        }
        // 添加列表滚动事件监听
        this.list_RecordLiquit.scrollBar.on(Laya.Event.CHANGE, this, this.onRecordListScroll);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CHARGE_RECORD, this, this.onChargeRecord);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_RECORD, this, this.onWithdrawRecord);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_TOKEN_CHANGE_RECORD, this, this.onAssetChangeRecord);
        // 列表渲染和选择处理
        this.list_day.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_day.selectHandler = new Laya.Handler(this, this.handleSelectToken);
    }

    onDisable(): void {
        this.Box_time.on(Laya.Event.CLICK, this, this.showTimePanel);
        for (let i = 0; i < 3; i++) {
            (this as any)["tab" + i].off(Laya.Event.CLICK, this, this.onTabClick);
        }
        // 移除列表事件
        this.list_day.renderHandler = null;
        this.list_day.selectHandler = null;
        // 添加列表滚动事件监听
        this.list_RecordLiquit.scrollBar.off(Laya.Event.CHANGE, this, this.onRecordListScroll);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CHARGE_RECORD, this, this.onChargeRecord);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_RECORD, this, this.onWithdrawRecord);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_TOKEN_CHANGE_RECORD, this, this.onAssetChangeRecord);
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     * @param isFromAsset 是否是从资产界面点击进来的
     */
    private onTabClick(index: number, isFromAsset: boolean = false): void {
        // 如果点击的是当前选中的tab且不是从资产界面点击进来的，直接返回
        if (this.m_currentTabIndex === index && !isFromAsset) {
            return;
        }
        this.m_currentTabIndex = index;

        // Tab相关常量定义
        const TAB_COUNT = 3;
        const SKIN_SELECTED = "res/common/comm/img_com_tab1.png";
        const SKIN_UNSELECTED = "res/common/comm/img_com_tab2.png";
        const COLOR_SELECTED = "#93401a";
        const COLOR_UNSELECTED = "#ffeed3";
        // 遍历所有Tab按钮
        for (let i = 0; i < TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            // this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isSelected ? SKIN_SELECTED : SKIN_UNSELECTED;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.color = isSelected ? COLOR_SELECTED : COLOR_UNSELECTED;

            if (isSelected) {
                AssetNewScene.isDepositRecord = index === 0;
                this.noDataBox.visible = false;
                switch (index) {
                    case 0:
                        this.list_Record.visible = false;
                        // this.list_deRecord.visible = true;
                        this.list_RecordLiquit.visible = false;
                        this.Box_time.visible = false;
                        // this.tf_dateTitle.x = 40;
                        this.historyBox.visible = false;
                        this.normalBox.visible = false;
                        this.normal2Box.visible = false;
                        this.normal2Box.visible = true;
                        HallWebSocket.send(com.snake.socket.MessageType.MSG_CHARGE_RECORD);
                        break;
                    case 1:
                        // this.list_Record.visible = true;
                        this.list_deRecord.visible = false;
                        this.list_RecordLiquit.visible = false;
                        this.Box_time.visible = false;
                        // this.tf_dateTitle.x = 40;
                        this.historyBox.visible = false;
                        this.normalBox.visible = true;
                        this.normal2Box.visible = false;
                        HallWebSocket.send(com.snake.socket.MessageType.MSG_WITHDRAW_RECORD);
                        break;
                    case 2:
                        this.list_Record.visible = false;
                        this.list_deRecord.visible = false;
                        this.Box_time.visible = true;
                        // this.tf_dateTitle.x = 29;
                        this.historyBox.visible = true;
                        this.normalBox.visible = false;
                        this.normal2Box.visible = false;
                        // this.list_Record.visible = true;
                        // 重置资产变更记录并请求第一页数据
                        this.resetAssetChangeList();
                        break;
                }
            }
        }
    }

    /**
     * 重置资产变更记录列表，准备重新加载第一页
     */
    private resetAssetChangeList(): void {
        // this.currentAssetChangePage = 1;
        this.isLoadingAssetChange = false;
        this.hasMoreAssetChange = true;
        this.assetChangeData = [];
        this.getAssetChangeData();
    }

    private initDate(): void {
        let sevendDayInfo = TimeUtil.getLastSevenDays();
        this.sevendDayInfoDisplay = sevendDayInfo.map((item: string) => {
            return TimeUtil.formatDateDisplay(item, GlobalDataManager.m_strLanguage == 7 || GlobalDataManager.m_strLanguage == 6);
        });
        this.list_day.array = this.sevendDayInfoDisplay;
        this.list_day.selectedIndex = 0;
    }

    showNoDataBox(listData:any[], tabIndex:number) {
        console.log("showNoDataBox", listData, this.m_currentTabIndex, tabIndex);
        if(this.m_currentTabIndex == tabIndex){
            if (!listData || listData.length === 0) {
                this.noDataBox.visible = true;
            } else {
                this.noDataBox.visible = false;
            }
        }
        
    }

    /**
     * 请求资产变更记录数据
     */
    private getAssetChangeData(): void {
        // 标记为正在加载
        this.isLoadingAssetChange = true;
        let date = this.sevendDayInfoDisplay[this.dayIndex].original;
        let dateDisplay = date.split("$").join("");
        // 创建请求消息体
        // 如果不是第一页，添加lastId参数
        let msgBody;
        if (this.assetChangeData.length > 0) {
            // if (this.currentAssetChangePage > 1 && this.assetChangeData.length > 0) {

            // 获取最后一项的ID
            const lastItem = this.assetChangeData[this.assetChangeData.length - 1];
            if (lastItem) {
                const recordData = JSON.parse(lastItem);
                const { id } = recordData;
                msgBody = new com.snake.socket.CS_TOKEN_CHANGE_RECORD({
                    pageSize: this.assetChangePageSize,
                    date: dateDisplay,
                    lastId: id
                });
            } else {
                msgBody = new com.snake.socket.CS_TOKEN_CHANGE_RECORD({
                    pageSize: this.assetChangePageSize,
                    date: dateDisplay
                });
            }
        } else {
            msgBody = new com.snake.socket.CS_TOKEN_CHANGE_RECORD({
                pageSize: this.assetChangePageSize,
                date: dateDisplay
            });
        }
        // 发送请求
        const cmdId = com.snake.socket.MessageType.MSG_TOKEN_CHANGE_RECORD;
        HallWebSocket.send(cmdId, msgBody);
    }

    private showTimePanel(): void {
        if (!this.img_time_pad.visible) {
            this.btn_hideBox.visible = true;
            this.img_time_pad.visible = true;
        } else {
            this.onCloseTab();
        }
    }

    private onChargeRecord(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CHARGE_RECORD = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CHARGE_RECORD);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            this.list_deRecord.array = msgBody.resp || [];
            // 设置列表为可滑动状态
            this.list_deRecord.vScrollBarSkin = ""; // 启用垂直滚动条
            this.list_deRecord.scrollBar.elasticDistance = 200; // 设置弹性滚动距离
            this.list_deRecord.scrollBar.rollRatio = 0.97; // 设置滚动衰减系数
            this.list_deRecord.visible = true;
            this.showNoDataBox(msgBody.resp, 0);
            // this.list_deRecord.visible = true;
        }
    }

    private onWithdrawRecord(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_WITHDRAW_RECORD = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_WITHDRAW_RECORD);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            this.list_Record.array = msgBody.resp || [];
            this.list_deRecord.visible = false;
            this.list_Record.visible = true;
            this.list_Record.vScrollBarSkin = ""; // 启用垂直滚动条
            this.list_Record.scrollBar.elasticDistance = 200; // 设置弹性滚动距离
            this.list_Record.scrollBar.rollRatio = 0.97; // 设置滚动衰减系数
            this.showNoDataBox(msgBody.resp, 1);
        }
    }

    /**
     * 关闭代币选择面板
     */
    private onCloseTab(): void {
        if (this.img_time_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_time_pad.visible = false;
        }
    }

    /**
     * 监听记录列表滚动事件
     */
    private onRecordListScroll(): void {
        console.log("onRecordListScroll", this.m_currentTabIndex, this.isLoadingAssetChange, this.hasMoreAssetChange);
        // 如果当前不是资产变更记录标签，或者正在加载，或者没有更多数据，则不处理
        if (this.m_currentTabIndex !== 2 || this.isLoadingAssetChange || !this.hasMoreAssetChange) {
            return;
        }

        // 计算滚动位置
        const scrollBar = this.list_RecordLiquit.scrollBar;
        const scrollPosition = scrollBar.value;
        const maxScrollPosition = scrollBar.max;

        // 当滚动到接近底部时加载下一页
        if (maxScrollPosition > 0 && scrollPosition >= maxScrollPosition * 0.8) {
            this.loadNextAssetChangePage();
        }
    }

    /**
     * 加载下一页资产变更记录数据
     */
    private loadNextAssetChangePage(): void {
        // 标记为正在加载
        this.isLoadingAssetChange = true;
        // 页码加1
        // this.currentAssetChangePage++;
        // 请求下一页数据
        this.getAssetChangeData();
    }

    /**
     * 处理资产变更记录响应
     */
    private onAssetChangeRecord(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 标记为加载完成
        this.isLoadingAssetChange = false;

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            const msgBody = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_TOKEN_CHANGE_RECORD);
            console.log(msgBody);

            if (msgBody && msgBody.records && msgBody.records.length > 0) {
                const newRecords = msgBody.records.map((item: any) => {
                    return item;
                });

                // 将新数据添加到现有数据中
                this.assetChangeData = this.assetChangeData.concat(newRecords);

                // 更新列表UI
                this.list_RecordLiquit.array = this.assetChangeData;
                
                this.list_RecordLiquit.visible = true;
                this.list_Record.visible = false;
                this.list_deRecord.visible = false;
                this.list_RecordLiquit.vScrollBarSkin = ""; // 启用垂直滚动条
                this.list_RecordLiquit.scrollBar.elasticDistance = 200; // 设置弹性滚动距离
                this.list_RecordLiquit.scrollBar.rollRatio = 0.97; // 设置滚动衰减系数
            } else {
                // 如果返回的数据为空，表示没有更多数据了
                // this.hasMoreAssetChange = false;
                // this.list_RecordLiquit.array = [];
                // this.list_RecordLiquit.visible = true;
                // // 如果是第一页且没有数据，显示空列表
                // if (this.currentAssetChangePage === 1) {
                //     this.list_RecordLiquit.array = [];
                //     this.list_RecordLiquit.visible = true;
                //     this.Box_time.visible = true;
                //     this.tf_dateTitle.x = 77
                // }
            }
            this.showNoDataBox(this.assetChangeData, 2);
        } else {
            // 请求失败处理
            // 页码减回去，以便重新请求
            // if (this.currentAssetChangePage > 1) {
            //     this.currentAssetChangePage--;
            // }
        }
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_day.selectedIndex == index);
            this.img_time_pad.visible = false;
            this.btn_hideBox.visible = false;
        }
    }

    private handleSelectToken(index: number): void {
        if (index != -1) {
            this.updateTokenInfo(index);
        }
    }

    private updateTokenInfo(index: number): void {
        this.dayIndex = index;
        this.assetChangeData = [];
        let data = this.list_day.array[index];
        this.list_RecordLiquit.array = this.assetChangeData
        // this.showNoDataBox(this.assetChangeData, 2);
        this.noDataBox.visible = false;
        this.tf_dayInfo.text = data.formatted;
        this.getAssetChangeData();
        console.log(data);
    }
}
