const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import { MemberMyListItemBase } from "./MemberMyListItem.generated";
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";
import { ComUtil } from "../../utils/ComUtil";

@regClass('/+8v/mmLR1CuN++HtoX+Uw==')
export class MemberMyListItem extends MemberMyListItemBase {
    public constructor() {
        super();
    }

    private referralData: any;

    public createChildren(): void {
        super.createChildren();
    }

    onEnable(): void {
        this.btnSetting.on(Laya.Event.CLICK, this, this.onOpenSettingDialog);
        Signal.on(GameEvent.EVENT_CHANGE_CLUB_RATE, this, this.onUpdateRate);
    }

    onDisable(): void {
        Signal.off(GameEvent.EVENT_CHANGE_CLUB_RATE, this, this.onUpdateRate);
    }

    public set dataSource(value: any) {
        if (!value) return;

        super.dataSource = value;
        let data = value.split(",");
        this.referralData = data;
        // this.btnSetting.visible = GlobalDataManager.clubCreater == GlobalDataManager.playerDto.pid
        // repeated string community=10;//成员（国家，头像，昵称，等级,推荐人数，rate）

        console.log("MemberMyListItem", value);
        this.img_flag.skin = GameResourceManager.getCountryIconById(data[1]);
        this.tf_name.text = ComUtil.fitTextToLabel(data[3], this.tf_name);;
        this.PlayerIcon.setHeadSkinAndRoldId(data[2], data[7]);
        this.tf_memberLevel.text = data[4];
        this.tf_referrals.text = data[5];
        let rate = ComUtil.multiplyWithPrecision(data[6], 100);
        this.tf_rate.text = `${rate}%`;
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(value) ?? 0;
        // 奇数行显示背景，偶数行不显示
        this.img_bg.visible = index % 2 === 1;
    }

    private onOpenSettingDialog() {
        ModuleManager.intance.openModule(ModuleName.SettingRateDialog, this.referralData);
    }

    private onUpdateRate(data: any): void {
        if (data && this.referralData && data.roleId === this.referralData[0]) {
            //data.rateValue先做一下四舍五入，保留三位小数
            // 计算百分比值（乘以100）
            this.referralData[6] = data.rateValue;
            const percentValue = data.rateValue * 100;
            // 四舍五入到三位小数
            const roundedValue = Math.round(percentValue * 1000) / 1000;
            // 转为字符串并去除结尾的0
            const formattedValue = parseFloat(roundedValue.toFixed(3)).toString();

            this.tf_rate.text = `${formattedValue}%`;
            // this.referralData.rate = data.rateValue;
        }
    }
}
