const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { LayerManager } from "../../common/LayerManager";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import GameSetting from "../../global/GameSetting";
import GlobalDataManager from "../../global/GlobalDataManager";
import NodeManager from "../../global/NodeManager";
import SheetDataManager from "../../global/SheetDataManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { ComUtil } from "../../utils/ComUtil";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { RoleInfoDialogBase } from "./RoleInfoDialog.generated";

@regClass('yxtp0TLDToWkAPu3Npm+3Q==')
export class RoleInfoDialog extends RoleInfoDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private roleInfo: com.snake.socket.RoleObject;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_copy.on(Laya.Event.CLICK, this, this.onCopy);
        Signal.on(GameEvent.EVENT_UPDATE_PLAYER_INFO, this, this.onRequestPlayerInfo);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CLUB_INFO, this, this.onClubInfoResponse);
    }

    public setOpenData(data: any) {
        GlobalDataManager.requestPlayerInfo(data);

        console.log("data", data);
    }

    /**
     * 获取玩家信息
     */
    public onRequestPlayerInfo(roleInfo: com.snake.socket.RoleObject): void {
        if (roleInfo) {
            this.roleInfo = roleInfo;
            this.updateBasicInfo();
            // if (msgBody.roleInfo.roleId == GlobalDataManager.this.roleInfo.pid) {
            // 不再从roleInfo获取invNum数据
        }
    }

    /**
     * 更新基本信息
     */
    private updateBasicInfo(): void {
        this.playerIcon.headSkin = this.roleInfo.icon; //头像
        this.tf_name.text = GameLanguageMgr.getLanguage(610100, "") + this.roleInfo.userName;
        const walletAddress = this.roleInfo.walletAddr;
        this.tf_address.text = GameLanguageMgr.getLanguage(610101, "") + ComUtil.shortenString(walletAddress, 6, 4);

        this.tf_createTime.text = `${TimeUtil.formatDateDDMMYYYY(this.roleInfo.createTime)}`;

        const countryItem = SheetDataManager.m_dicCountry.get(this.roleInfo.country);
        if (countryItem) {
            this.tf_country.text = GameLanguageMgr.getLanguage(countryItem.name);
            this.img_country.skin = GameResourceManager.getCountryIcon(countryItem.icon);
        }

        // this.tf_roleId.text = this.roleInfo.roleId;
        var myTotalNum = "0";
        var mybestScore = "0";
        var myTotalKill = "0";
        var records = this.roleInfo.record;
        if (records && records.length > 0) {
            for (var i = 0; i < records.length; i++) {
                var datas = records[i].split(",");
                if (GameSetting.gameId == parseInt(datas[0])) {
                    myTotalNum = datas[1];
                    mybestScore = datas[2];
                    myTotalKill = datas[3];
                    break;
                }
            }
        }
        this.tf_totalNum.text = myTotalNum;
        this.tf_bestScore.text = mybestScore;
        this.tf_totalKill.text = myTotalKill;

        this.tf_level.text = `${this.roleInfo.lv}`;

        // this.tf_totalNum.text = `${this.roleInfo.num}`;
        // this.tf_totalKill.text = `${this.roleInfo.kills}`;
        // this.tf_kill.text = `${this.roleInfo.maxKill}`;

        // // 使用HTML样式标签，让数字和单位"s"底部对齐
        // this.tf_longTime.text = `<span style="color:#6aeb2b;font-size:46px;">${this.roleInfo.maxAlive}</span><span style="color:#6aeb2b;font-size:32px;vertical-align:bottom;">s</span>`;

        // 请求俱乐部信息
        if (this.roleInfo.club) {
            this.requestClubInfo(this.roleInfo.club);
        }
    }

    /**
     * 请求俱乐部信息
     */
    private requestClubInfo(clubId: string): void {
        // 创建请求消息体
        let point = NodeManager.getNodePoint();
        const requestData = com.snake.socket.CS_CLUB_INFO.fromObject({ point: point, clubId: Number(clubId) });

        // 发送请求
        const cmdId = com.snake.socket.MessageType.MSG_CLUB_INFO;
        // 使用HallWebSocket发送请求
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 处理俱乐部信息响应
     */
    private onClubInfoResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CLUB_INFO = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CLUB_INFO);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("SC_CLUB_INFO", msgBody);
            // 更新俱乐部名称
            this.tf_clubName.text = ComUtil.truncateUnicodeString(msgBody.name, 30);
        }
    }

    /**
     * 复制钱包地址
     */
    onCopy() {
        if (this.roleInfo) {
            let shareUrl = this.roleInfo.walletAddr;
            doCopy(shareUrl);
            NoticeMgr.notice(GameLanguageMgr.getLanguage(19)); //复制成功
        }
    }

    onDisable(): void {
        Signal.off(GameEvent.EVENT_UPDATE_PLAYER_INFO, this, this.onRequestPlayerInfo);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CLUB_INFO, this, this.onClubInfoResponse);

        Signal.offAllCaller(this);
    }
}
