/**
 * 连击计数器UI组件
 */
export class ComboCounter {
    private container: Laya.Sprite;
    private comboLabel: Laya.Label;
    private comboIcon: Laya.Image;
    private currentCombo: number = 0;
    private isVisible: boolean = false;

    constructor() {}

    /**
     * 初始化连击计数器
     * @param parent 父容器
     * @param x X坐标
     * @param y Y坐标
     */
    public init(box_hitsCount: Laya.Box, img_hitsCount: Laya.Image, tf_hitsCount: Laya.Label): void {
        this.container = box_hitsCount;
        this.comboIcon = img_hitsCount;
        this.comboLabel = tf_hitsCount;

        // 初始状态
        this.updateCombo(0);
    }

    /**
     * 更新连击数
     * @param combo 连击数
     */
    public updateCombo(combo: number): void {
        this.currentCombo = combo;

        if (combo > 1) {
            this.show();
            this.comboLabel.text = `${combo}`;

            // 连击动画效果
            this.playComboAnimation();

            // 根据连击数改变颜色
            this.updateComboColor(combo);
        } else {
            this.hide();
        }
    }

    /**
     * 显示连击计数器
     */
    private show(): void {
        if (this.isVisible) return;

        this.isVisible = true;
        this.container.visible = true;

        // 显示动画
        this.container.scaleX = 0;
        this.container.scaleY = 0;
        this.container.alpha = 0;

        Laya.Tween.to(
            this.container,
            {
                scaleX: 1,
                scaleY: 1,
                alpha: 1
            },
            300,
            Laya.Ease.backOut
        );
    }

    /**
     * 隐藏连击计数器
     */
    private hide(): void {
        if (!this.isVisible) return;

        this.isVisible = false;

        Laya.Tween.to(
            this.container,
            {
                scaleX: 0,
                scaleY: 0,
                alpha: 0
            },
            200,
            Laya.Ease.backIn,
            Laya.Handler.create(this, () => {
                this.container.visible = false;
            })
        );
    }

    /**
     * 播放连击动画
     */
    private playComboAnimation(): void {
        // 文本缩放动画
        const originalScale = this.comboLabel.scaleX;
        Laya.Tween.to(
            this.comboLabel,
            {
                scaleX: 1.5,
                scaleY: 1.5
            },
            150,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(
                    this.comboLabel,
                    {
                        scaleX: originalScale,
                        scaleY: originalScale
                    },
                    150,
                    Laya.Ease.backOut
                );
            })
        );

        // 图标旋转动画
        Laya.Tween.to(
            this.comboIcon,
            {
                rotation: this.comboIcon.rotation + 360
            },
            500,
            Laya.Ease.backOut
        );
    }

    /**
     * 根据连击数更新颜色
     * @param combo 连击数
     */
    private updateComboColor(combo: number): void {
        let color = "#FF6B6B"; // 默认红色

        if (combo >= 10) {
            color = "#FFD700"; // 金色
        } else if (combo >= 7) {
            color = "#DDA0DD"; // 紫色
        } else if (combo >= 5) {
            color = "#FFEAA7"; // 黄色
        } else if (combo >= 3) {
            color = "#96CEB4"; // 绿色
        }
        this.comboLabel.color = color; // 更新图标颜色
       }

    /**
     * 重置连击计数器
     */
    public reset(): void {
        this.updateCombo(0);
    }

    /**
     * 获取当前连击数
     */
    public getCurrentCombo(): number {
        return this.currentCombo;
    }

    /**
     * 销毁
     */
    public destroy(): void {
        if (this.container.parent) {
            this.container.removeSelf();
        }
        this.container = null;
        this.comboLabel = null;
        this.comboIcon = null;
    }
}
