const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { TokenData } from "../../data/dto/TokenData";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import KnapsackManager from "../../global/KnapsackManager";
import NodeManager from "../../global/NodeManager";
import SheetDataManager from "../../global/SheetDataManager";
import AssetManager from "../../manager/AssetManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { ComUtil } from "../../utils/ComUtil";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { CreateClubRoomDialogBase } from "./CreateClubRoomDialog.generated";

@regClass('Trnh8WLVQT+6W4h3KUeNgA==')
export class CreateClubRoomDialog extends CreateClubRoomDialogBase {
    private roomMoney: number = 0;
    private isCreating: boolean = false;
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private roomData: any;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_create.on(Laya.Event.CLICK, this, this.onCreate);
        this.btn_shop.on(Laya.Event.CLICK, this, this.onGoShop);
        this.CardBox.on(Laya.Event.CLICK, this, this.showSelecePanel);
        this.TokenBox.on(Laya.Event.CLICK, this, this.showTokenPanel);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_tip.on(Laya.Event.CLICK, this, this.onShowTip);
        this.ticketInput.on(Laya.Event.INPUT, this, this.testTicketMoneyInput);
        Signal.on(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        Signal.on(GameEvent.EVENT_ITEM_UPDATE, this, this.onPackInfo);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CREATE_CUSTOM_ROOM, this, this.onCreateRoomResponse);
        // 列表渲染和选择处理
        this.list_item.renderHandler = Laya.Handler.create(this, this.onTimeItemRender, null, false);
        this.list_item.selectHandler = new Laya.Handler(this, this.handleSelectTime);
        // 列表渲染和选择处理
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
        this.initBagInfo();

        // 初始化隐藏提示
        this.img_tel.visible = false;
        this.btn_hideBox.visible = false;
        if (!AssetManager.getTokenData()) {
            this.requestCoinInfo();
        } else {
            this.showTokenArray(AssetManager.getTokenData());
            // this.onTabClick(0);
        }
    }

    /**
     * 列表项渲染处理
     */
    private onTimeItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_item.selectedIndex == index);
            this.img_card_pad.visible = false;
            this.btn_hideBox.visible = false;
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectTime(index: number): void {
        if (index != -1) {
            // this.roomIndex = index;
            let roomItem: any = this.list_item.selectedItem;
            const itemItem: ItemItem = SheetDataManager.m_dicItems.get(roomItem.id);
            this.img_card.skin = GameResourceManager.getItemIcon(itemItem);
            this.tf_cardName.text = `${GameLanguageMgr.getLanguage(itemItem.name)} X${roomItem.count}`;
            switch (itemItem.id) {
                case 1101:
                    //小时卡
                    this.tf_maxTime.text = "1 Hour";
                    break;
                case 1102:
                    //天卡
                    this.tf_maxTime.text = "1 Day";
                    break;
                case 1103:
                    //周卡
                    this.tf_maxTime.text = "1 Week";
                    break;
                default:
                    this.tf_cardName.text = `${GameLanguageMgr.getLanguage(itemItem.name)} X${roomItem.count}`;
            }
            console.log(roomItem);
            // this.updateTokenInfo(index);
        }
    }

    private onCreate() {
        if (this.isCreating) {
            return;
        }

        if (this.roomMoney <= 0) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(58));
            return;
        }
        //从this.roomData筛选出this.list_token.selectedItem的index
        let index = this.roomData.ticketType.findIndex((item: any) => item === this.list_token.selectedItem);
        let minTicketAmount = this.roomData.minTicketAmount[index];
        let tokenData = AssetManager.getTokenDataBySyId(this.list_token.selectedItem);
        if (this.roomMoney < minTicketAmount) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(92, minTicketAmount, tokenData.symbol));
            return;
        }
        // let index =

        // 设置创建状态为true，防止连点
        this.isCreating = true;

        // 构造房间参数（这里需要根据实际UI填写参数，以下为示例）
        const itemId = this.list_item.selectedItem.id;
        let point = NodeManager.getNodePoint();
        const msgBody = new com.snake.socket.CS_CREATE_CUSTOM_ROOM({
            type: 2, // 房间类型
            ticketId: this.list_token.selectedItem, // 门票ID
            ticketValue: this.roomMoney, // 门票价格
            map: "Bluemarks", // 地图
            fruit: "apple", // 道具
            bgm: "Munch Dance", // 背景音乐
            point: point, // 节点
            itemId: itemId // 道具ID
        });
        const cmdId = com.snake.socket.MessageType.MSG_CREATE_CUSTOM_ROOM;
        HallWebSocket.send(cmdId, msgBody);

        // 3秒后恢复状态
        Laya.timer.once(3000, this, () => {
            this.isCreating = false;
        });
    }

    private onGoShop() {
        this.close();
        SceneManager.setCurrentScene(SceneType.M_SCENE_SHOP, [2]);
    }

    private initBagInfo() {
        // 发送获取背包信息请求
                GlobalDataManager.requestPackInfo();
    }

    /**
     * 背包信息返回处理
     */
    private onPackInfo(): void {
        const cardList = [1101, 1102, 1103];

        // 使用数组存储卡片信息
        const cardsInfo: Array<{ id: number; count: number }> = [];
        let hasAnyCard = false;

        // 初始化卡片数组
        cardList.forEach((cardId) => {
            cardsInfo.push({
                id: cardId,
                count: 0
            });
        });

        // 遍历背包物品，找出对应的卡片并记录数量

        KnapsackManager.getAllKnapsackItems().forEach((item) => {
            const cardIndex = cardList.indexOf(item.id);
            if (cardIndex !== -1) {
                cardsInfo[cardIndex].count = item.num || 0;
            }
        });

        // 过滤掉数量为0的卡片
        const filteredCardsInfo = cardsInfo.filter((card) => card.count > 0);
        // 检查是否存在卡片
        hasAnyCard = filteredCardsInfo.length > 0;

        // 如果没有找到任何卡片，设置相应的UI状态
        if (!hasAnyCard) {
            this.btn_create.disabled = true;
            this.tf_itemNo.visible = true;
            this.btn_shop.visible = true;
            this.CardBox.visible = false;
        } else {
            this.btn_create.disabled = false;
            this.tf_itemNo.visible = false;
            this.btn_shop.visible = false;
            this.CardBox.visible = true;
        }
        this.list_item.array = filteredCardsInfo;
        this.showDefaultCard(filteredCardsInfo);
    }

    /**
     * 创建房间回包处理
     */
    private onCreateRoomResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CREATE_CUSTOM_ROOM = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CREATE_CUSTOM_ROOM);
        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL) {
            // 创建成功
            NoticeMgr.notice(GameLanguageMgr.getLanguage(56));
            const cmdId = com.snake.socket.MessageType.MSG_CLUB_ROOM;
            HallWebSocket.send(cmdId);
            this.close();
        } else if (msgcode === com.snake.socket.MessageCode.CREATE_ROOM_MAX) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(59));
        }
    }

    onDisable(): void {
        this.btn_create.off(Laya.Event.CLICK, this, this.onCreate);
        this.btn_shop.off(Laya.Event.CLICK, this, this.onGoShop);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_tip.off(Laya.Event.CLICK, this, this.onShowTip);
        Signal.off(GameEvent.EVENT_ITEM_UPDATE, this, this.onPackInfo);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CREATE_CUSTOM_ROOM, this, this.onCreateRoomResponse);
        Signal.off(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);

        // 清除可能存在的定时器
        Laya.timer.clear(this, () => {
            this.isCreating = false;
        });
    }

    private onCloseTab(): void {
        if (this.img_card_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_card_pad.visible = false;
        }
        if (this.img_tel.visible) {
            this.btn_hideBox.visible = false;
            this.img_tel.visible = false;
        }
        if (this.img_token_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_token_pad.visible = false;
        }
    }

    private showSelecePanel() {
        this.img_card_pad.visible = true;
        this.btn_hideBox.visible = true;
    }

    private showTokenPanel() {
        this.img_token_pad.visible = true;
        this.btn_hideBox.visible = true;
    }

    private showDefaultCard(propData: any[]) {
        // 查找第一个count不为0的物品索引
        const firstValidIndex = propData.findIndex((item) => item.count > 0);
        if (firstValidIndex !== -1) {
            // 设置选中项
            this.list_item.selectedIndex = firstValidIndex;
            // 触发选择处理
            this.handleSelectTime(firstValidIndex);
        }
    }

    /**
     * 显示提示信息
     */
    private onShowTip(): void {
        this.img_tel.visible = true;
        this.btn_hideBox.visible = true;
    }

    /**
     * 请求资产信息
     */
    public requestCoinInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_QUERY_TOKEN;
        HallWebSocket.send(cmdId);
    }

    /**
     * 获取资产信息回调
     */
    private onRequestInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        const msgBody: com.snake.socket.SC_QUERY_TOKEN = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_QUERY_TOKEN);

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析成可用的object格式
            const parsedTokens = ComUtil.parseTokenData(msgBody.token);
            //parsedTokens里面所有项目的symbolId都保存到allTokenData

            this.showTokenArray(parsedTokens);
        }
    }

    private showTokenArray(parsedTokens: TokenData[]): void {
        let allTokenData: number[] = [];
        const dic = SheetDataManager.m_dicRoom?.values;
        let roomType = 5;
        const roomItems = dic.filter((item) => item.roomType == roomType)[0] as any;
        console.log(roomItems);

        parsedTokens.forEach((item) => {
            allTokenData.push(item.symbolId);
        });
        this.roomData = roomItems;
        // this.list_token.array = allTokenData;
        if (roomItems && roomItems.ticketType) {
            this.list_token.array = roomItems.ticketType;
        }
        this.list_token.selectedIndex = 0;
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_token.selectedIndex == index);
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        if (index != -1) {
            // 使用下标直接获取数据，而不是通过symbolId查找
            let symbolId = this.roomData.ticketType[index];
            // const tokenData = AssetManager.getTokenData()[index];
            // const tokenData = AssetManager.getTokenData()[index];
            let tokenData = AssetManager.getTokenDataBySyId(symbolId);
            if (tokenData) {
                this.tf_tokenName.text = tokenData.symbol;
            }
            // if (tokenData) {
            //     this.tf_tokenName.text = tokenData.symbol;
            // }
        }
        this.img_token_pad.visible = false;
        this.btn_hideBox.visible = false;
    }

    /**
     * 验证充值码输入
     * 限制只能输入数字和小数点，且只能输入正数
     */
    private testTicketMoneyInput(): void {
        const value = this.ticketInput.text;
        if (value) {
            // 正则表达式验证：只允许输入正数（整数或小数）
            const reg = /^[0-9]+\.?[0-9]*$/;

            // 检查是否为负数或非法字符
            if (!reg.test(value)) {
                // 过滤掉非法字符，只保留数字和小数点
                let filteredValue = "";
                for (let i = 0; i < value.length; i++) {
                    const char = value.charAt(i);
                    if ((char >= "0" && char <= "9") || (char === "." && filteredValue.indexOf(".") === -1)) {
                        filteredValue += char;
                    }
                }

                // 更新输入框内容
                this.ticketInput.text = filteredValue;
            }

            // 确保不是0开头的多位数（除非是小数）
            if (value.length > 1 && value.startsWith("0") && value.charAt(1) !== ".") {
                this.ticketInput.text = value.substring(1);
            }
            this.roomMoney = Number(this.ticketInput.text);
        }
    }
}
