import { com } from "../../network/pb/socket";
import { Dictionary } from "../../utils/Dictionary";
import Constants from "../../global/config/Constants";
import { Vec2 } from "../../utils/Vec2";
import { Collision } from "../collision/Collision";
import { BodySkin } from "./BodySkin";
import { BodySkinPool } from "./BodySkinPool";
import Snake from "./Snake";
import GlobalDataManager from "../../global/GlobalDataManager";
import MatchModel from "../../modules/match/MatchModel";

import SheetDataManager from "../../global/SheetDataManager";
import FoodManager from "../food/FoodManager";
import { SnakeLengthRuleItem } from "../../data/sheetItem/snake/SnakeLengthRuleItem";
import { SC_EAT_FOOD } from "../../data/dto/SC_EAT_FOOD";
import MapManager from "../map/MapManager";

abstract class SnakeManagerBase {
    protected static _instance: SnakeManagerBase | null = null;
    /**
     * 所有英雄spr 字典
     */
    public matchHeroSprDic: Dictionary;

    container: Laya.Sprite;
    selfSnake: Snake | null = null;

    skinLen: number; //总长度
    kills: number; //总击杀
    kingId: string; //蛇王ID

    protected collision: Collision;

    private bodySkinPool: BodySkinPool;

    /** 是否在控制中 */
    public isControl: boolean = false;

    init() {
        if (!this.container) this.container = new Laya.Sprite();
        // this.snakes = [];
        this.matchHeroSprDic = new Dictionary(true);
        // this.diedSnakeDic = new Dictionary();
        // this.eatFoodDic = new Dictionary();
        this.selfSnake = null;
        // 初始化碰撞模块，传入地图区域边界
        // const bounds = new Laya.Rectangle( 0, 0, Constants.mapSize.width, Constants.mapSize.height );
        this.collision = Collision.getInstance(null);

        this.bodySkinPool = new BodySkinPool(this.container);
        // this.tagManager = TagManager.getInstance();
    }

    /**
     * 创建一条蛇，并添加到管理器中
     * @param pos 蛇的初始位置（Laya.Point）
     * @param dir 蛇的初始方向（Vec2 类型）
     * @param len 蛇的骨骼数量
     * @param snakeType 蛇的类型，默认为其他蛇
     */
    public abstract createSnake(roomPlayerDto: com.snake.socket.PlayerObject): Snake;

    public updateSnake(snake: Snake, roomPlayerDto: com.snake.socket.PlayerObject): Snake {
        console.log("updateSnake: " + roomPlayerDto.roleId, GlobalDataManager.playerDto.pid);

        snake.updateData(roomPlayerDto);

        if (GlobalDataManager.playerDto.pid == roomPlayerDto.roleId) {
            this.selfSnake = snake;
        }

        return snake;
    }

    public addBodySkin(bodySkin: BodySkin) {
        this.collision.addBodySkin(bodySkin);
    }
    public removeBodySkin(bodySkin: BodySkin) {
        this.collision.removeBodySkin(bodySkin);
    }

    public updateSnakes(dt: number, isLogicSnake: boolean, hasConfirmed: boolean, needMove: boolean): void {
        // 移动所有蛇
        this.moveSnakes(dt, isLogicSnake, hasConfirmed, needMove);

        // 刷新四叉树
        this.collision.refresh();

        this.checkAllSnakeCollision(isLogicSnake, hasConfirmed);
    }

    getSnake(roleId: string) {
        return this.matchHeroSprDic.get(roleId);
    }

    public abstract removeSnake(roleId: string):void;
    removeAllSnakes() {
        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            (snake as Snake).destroy();
        }

        this.matchHeroSprDic = new Dictionary(true);
    }
    /**
     * 更新所有蛇的状态（移动、检查死亡、更新碰撞四叉树）
     * @param dt 时间增量（秒）
     */
    public moveSnakes(dt: number, isLogicSnake: boolean, hasConfirmed: boolean, needMove: boolean): void {
        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            if ((snake as Snake).isAlive(isLogicSnake)) {
                (snake as Snake).move(dt, isLogicSnake, hasConfirmed, needMove);
            }
        }
    }

    /**
     * 设置蛇的目标旋转方向
     * @param snakeType 蛇类型
     * @param dir 目标方向（Vec2 类型）
     */
    public abstract rorate(snakeType: number, direction: number): void;

    /**
     * 更新蛇的移动速率
     * @param snakeType 蛇类型
     * @param rate 速率值
     */
    public abstract updateSpeedRate(snakeType: number, rate: number): void;

    /**
     * 获取玩家控制蛇的头部位置
     */
    public getSelfSnakePos(isLogicSnake: boolean): Vec2 | null {
        if (this.selfSnake) {
            return this.selfSnake.getHeadPosition(isLogicSnake);
        }
        return null;
    }

    /**
     * 检查蛇是否碰撞死亡：
     * - 检查蛇头是否撞边界
     * - 检查蛇头与其他蛇之间的碰撞
     */
    public abstract checkAllSnakeCollision(isLogicSnake: boolean, hasConfirmed: boolean): void;

    createSnakes() {
        this.matchHeroSprDic = new Dictionary(true);

        let len = MatchModel.matchDto.members.length;

        for (var i = 0; i < len; i++) {
            var roomPlayerDto: com.snake.socket.PlayerObject = MatchModel.matchDto.members[i];

            var snake: Snake = this.createSnake(roomPlayerDto);
        }
    }

    newAddSnake(roomPlayerDto: com.snake.socket.PlayerObject) {
        // try {
        var snake: Snake = this.matchHeroSprDic.get(roomPlayerDto.roleId);
        if (snake) {
            this.updateSnake(snake, roomPlayerDto);
        } else {
            snake = this.createSnake(roomPlayerDto);
        }
    }

    restoreSnakes() {
        this.removeAllSnakes();
        this.matchHeroSprDic = new Dictionary(true);

        let len = MatchModel.matchDto.members.length;

        for (var i = 0; i < len; i++) {
            var roomPlayerDto: com.snake.socket.PlayerObject = MatchModel.matchDto.members[i];

            try {
                var snake: Snake = this.createSnake(roomPlayerDto);
            } catch (error) {
                console.warn(error);
            }
        }
    }

    /**
     * 获取排除当前蛇的所有身体皮肤节点
     * @param excludeSnake
     * @param isLogicSnake
     * @returns
     */
    getBodySkinsWithOutOne(excludeSnake: Snake, isLogicSnake: boolean): BodySkin[] {
        var bodySkins: BodySkin[] = [];
        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            var playerSnake: Snake = snake;
            if (playerSnake.tag && excludeSnake.tag.roleId != playerSnake.tag.roleId) {
                bodySkins = bodySkins.concat(playerSnake.getSkins(isLogicSnake));
            }
        }
        return bodySkins;
    }

    public getBodySkinPool(): BodySkinPool {
        return this.bodySkinPool;
    }

    showLogInHead(str: string, isLogicSnake: boolean) {
        if (this.selfSnake && this.selfSnake.tag) this.selfSnake.showLogInHead(str, isLogicSnake);
    }

    countSnakeLen(snakeId: number, skinLength: number, totalScore: number, intervalBoneToDrawSkin: number): number {
        var targetLen = skinLength + 1;
        var nextSnakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(SheetDataManager.m_dicSnakeLengthRules, [
            snakeId,
            skinLength + 1
        ]);
        if (nextSnakeLengthRuleItem) {
            if (totalScore >= nextSnakeLengthRuleItem.accumulatePoints) {
                //大于等于累计积分
                return this.countSnakeLen(snakeId, targetLen, totalScore, intervalBoneToDrawSkin);
            } else {
                return skinLength * intervalBoneToDrawSkin;
            }
        } else {
            return skinLength * intervalBoneToDrawSkin;
        }
    }

    public getRoleById(roleId: string): Snake {
        if (this.matchHeroSprDic) return this.matchHeroSprDic.get(roleId);
        else return null;
    }

    public getFirstSnake(): Snake {
        if (this.matchHeroSprDic) {
            var value = this.matchHeroSprDic.getFirstEntry();
            return value;
        } else return null;
    }

    setMyHeroDirection(direction: number) {
        var isWatch = MatchModel.matchWatcher;
        if (isWatch) {
            MapManager.setMapDirection(direction);
        } else {
            if (!this.selfSnake) return;
            if (direction != -4) {
                this.rorate(Constants.snakeType.SELF, direction);
                this.isControl = true;
            } else {
                this.isControl = false;
            }
        }
    }

    eatFoodAndAddScore(msgEatFoodBody: SC_EAT_FOOD, isLogicSnake: boolean) {
        var fids = msgEatFoodBody.fid; //食物id
        var score = msgEatFoodBody.score; //当前积分
        var lenght = msgEatFoodBody.lenght; //当前长度
        var roleId = msgEatFoodBody.roleId; //玩家id

        var snake: Snake = this.getRoleById(roleId);
        if (snake) {
            snake.setLength(lenght, isLogicSnake); //更新蛇的长度
            // snake.len = lenght;
            FoodManager.eateFoodIds(snake, fids, score, isLogicSnake);
            snake.setScore(score, isLogicSnake);
        }
    }

    public clear(): void {
        this.removeAllSnakes();
        this.container.removeSelf();
        this.container = null;
        this.selfSnake = null;

        this.matchHeroSprDic = null;
        this.bodySkinPool.clear();
        this.collision = null;
    }
}
export default SnakeManagerBase;
