    /**
     * TON钱包充值
     * @param params TON充值参数
     * @returns 交易哈希或undefined（失败时）
     */
    async rechargeTON2(params: TonRechargeParams) {
        const recipientAddress = params.rechargeAddress;
        let appId = GameSetting.gameId;
        const client = new TonClient({
            endpoint: "https://toncenter.com/api/v2/jsonRPC" // 主网 RPC
        });
        const forwardPayload = beginCell().storeInt(appId, 32).storeInt(0, 32).endCell();

        // USDT 合约地址
        const masterContract = Address.parse(params.token);
        // 自己钱包地址
        const myAddress = Address.parse(EthereumManager.walletAddress);

        // 查询子钱包地址
        const walletAddressRes = await client.runMethod(masterContract, "get_wallet_address", [
            { type: "slice", cell: beginCell().storeAddress(myAddress).endCell() }
        ]);

        // 5. 解析 Jetton 子钱包地址
        const jettonWalletAddress = walletAddressRes.stack.readAddress();

        console.log("你的 Jetton 子钱包地址是：", jettonWalletAddress.toString());

        // USDT 子钱包地址
        const usdtContractAddress = jettonWalletAddress.toString();

        // 接收方钱包地址

        // 转账金额 USDT（6位小数）
        const usdtAmount = params.amount * 1e6;
        console.log("forwardPayload", forwardPayload);
        const payloadCell = beginCell()
            .storeUint(0xf8a7ea5, 32) // Jetton transfer opcode
            .storeUint(0, 64) // query_id
            .storeCoins(usdtAmount) // amount - 使用与成功交易一致的值
            .storeAddress(Address.parse(recipientAddress)) // destination
            .storeAddress(Address.parse(EthereumManager.walletAddress)) // response_destination
            .storeBit(0) // custom_payload: 没有
            .storeCoins(toNano("0.01")) // forward_ton_amount
            // .storeBit(0) // custom_payload: 没有
            .storeSlice(forwardPayload.beginParse()) // forwardPayload
            .endCell();
        const request = {
            validUntil: Math.floor(Date.now() / 1000) + 300, // 5分钟有效期
            messages: [
                {
                    address: usdtContractAddress, // USDT 合约地址
                    amount: toNano("0.08").toString(), // 0.15 TON（Gas 费）
                    payload: payloadCell.toBoc().toString("base64") // 转账 payload
                }
            ]
        };

        const result = await EthereumManager.tonConnectUI.sendTransaction(request);
        console.log("Transaction:", result.boc);
        return result.boc;
    }
