const { regClass } = Laya;
import { PopTipDialogBase } from "./PopTipDialog.generated";

@regClass('4EsypZIjQSCpG8613FUEzQ==')
export class PopTipDialog extends PopTipDialogBase {
    private canClose: boolean = true;
    // public m_iLayerType: number = LayerManager.M_TOP;
    isPopupCenter = false;
    public constructor() {
        super();
    }

    onEnable(): void {}

    public setOpenData(data: any) {
        if (data) {
            this.alertDesc.text = data[0] as string;
            var point = data[1] as Laya.Point;
            if (point) {
                var px = point.x - 422;
                var py = point.y - 294;
                // this.pos(0, 0);
                this.pos(px, py);
                // console.log("============ point", px, py);
                // this.isPopupCenter = true;
            }

            this.alertDesc.height = this.alertDesc.textField.textHeight + 20;
        }
    }

    onDisable(): void {}

    close(type?: string): void {
        if (this.canClose) super.close(type);
    }
}
