const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { EnumConsumeType } from "../../data/enumData/EnumConsumeType";
import { CountryItem } from "../../data/sheetItem/CountryItem";
import { HeadItem } from "../../data/sheetItem/HeadItem";
import HttpCmd from "../../network/HttpCmd";
import { Dictionary } from "../../utils/Dictionary";
import { SelectHeadDialogBase } from "./SelectHeadDialog.generated";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import GlobalDataManager from "../../global/GlobalDataManager";

import NoticeMgr from "../notice/NoticeMgr";
import SheetDataManager from "../../global/SheetDataManager";

@regClass('3CibwwHGSPG2Qkeq4rbMag==')
export class SelectHeadDialog extends SelectHeadDialogBase {
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    public setOpenData(_data: any) {}

    onEnable(): void {
        this.list_head.vScrollBarSkin = "";
        this.btn_confirm.on(Laya.Event.CLICK, this, this.onRegister);
        this.btn_custom.on(Laya.Event.CLICK, this, this.onBtnChangePic);
        this.input_name.prompt = GameLanguageMgr.getLanguage(25);
        this.initContainer();
        let goldDatas = SheetDataManager.getGeneralValueById(13);
        this.tf_nameGold.text = goldDatas[1];
        this.img_nameGold.skin = GameResourceManager.getMoneyIcon(goldDatas[0]); // `gameIcon/items/item/img_${goldDatas[0]}.png`;
        console.log(goldDatas);
    }

    private initContainer(): void {
        this.list_head.vScrollBarSkin = "";
        this.list_head.selectHandler = new Laya.Handler(this, this.handleSelectHead);
        this.createHeadList();
        this.initCountry();
    }

    private handleSelectHead(index: number): void {
        if (index != -1) {
            let headItem: HeadItem = this.list_head.selectedItem;
            GlobalDataManager.headId = headItem.id;
            this.playerIcon.headSkin = GlobalDataManager.headId;
        }
    }

    private createHeadList(): void {
        let m_dicHead: Dictionary = SheetDataManager.m_dicHead;
        this.list_head.array = m_dicHead.values;
        this.list_head.visible = true;
        let selectIndex = -1;
        let i = 0;
        GlobalDataManager.headId = GlobalDataManager.playerDto.icon;
        this.playerIcon.headSkin = GlobalDataManager.headId; //设置当前角色头像；
        this.input_name.text = GlobalDataManager.playerDto.name;
        for (let entry of m_dicHead.values) {
            if (entry.id == GlobalDataManager.headId) {
                selectIndex = i;
                break;
            }
            i++;
        }
        this.list_head.selectedIndex = selectIndex;
    }

    //=======================  国家  ====================
    initCountry() {
        this.list_country.selectHandler = new Laya.Handler(this, this.handleSelectCountry);
        this.createCountryList();
        this.box_country.on(Laya.Event.CLICK, this, this.onOpenCountry);
        this.list_country.on(Laya.Event.MOUSE_DOWN, this, this.onListDown);
        this.list_country.mouseHandler = Laya.Handler.create(this, this.onCountryItemMouse, null, false);
        this.list_country.renderHandler = Laya.Handler.create(this, this.onCountryItemRender, null, false);
        if (this.list_country.scrollBar) this.list_country.scrollBar.on(Laya.Event.MOUSE_DOWN, this, this.onScrollBarDown);
    }

    /**
     * @private
     * 下拉列表的鼠标事件响应函数。
     */
    protected onCountryItemMouse(e: Event, index: number): void {
        let type: string = e.type;
        if (type === Laya.Event.CLICK) {
            this.list_country.selectedIndex = index;
            this.onHideCountry();
            // this.isOpen = false;
        }
    }

    private onListDown(e: Event): void {
        e.stopPropagation();
    }

    private onScrollBarDown(e: Event): void {
        e.stopPropagation();
    }

    private onCountryItemRender(cell: any, index: number): void {
        cell.onChange(this.list_country.selectedIndex == index);
    }

    private onOpenCountry() {
        if (this.img_country_pad.visible == false) {
            this.img_country_pad.visible = true;
            Laya.stage.once(Laya.Event.MOUSE_DOWN, this, this.onHideCountry);
        }
    }

    private onHideCountry() {
        this.img_country_pad.visible = false;
        Laya.stage.off(Laya.Event.MOUSE_DOWN, this, this.onHideCountry);
    }

    private handleSelectCountry(index: number): void {
        console.log("handleSelectCountry: " + index);
        if (index != -1) {
            let countryItem: CountryItem = this.list_country.selectedItem;
            GlobalDataManager.countryId = countryItem.id;
            this.img_flag.skin = GameResourceManager.getCountryIcon(countryItem.icon);
            this.tf_country.text = GameLanguageMgr.getLanguage(countryItem.name);
        }
    }

    private createCountryList(): void {
        let m_dicCountry: Dictionary = SheetDataManager.m_dicCountry;

        this.list_country.array = m_dicCountry.values;
        this.list_country.visible = true;
        let selectIndex = -1;
        let i = 0;
        GlobalDataManager.countryId = GlobalDataManager.playerDto.country;
        for (let entry of m_dicCountry.values) {
            if (entry.id == GlobalDataManager.countryId) {
                selectIndex = i;
                break;
            }
            i++;
        }
        this.list_country.selectedIndex = selectIndex;
    }

    /** 切换 用户上传图片  */
    onBtnChangePic(): void {
        var zIndex = Laya.Render.canvas.style.zIndex;
        var uploadP = GameLanguageMgr.getUILang("Upload picture");
        var selectI = GameLanguageMgr.getUILang("Select Image");
        var saveC = GameLanguageMgr.getUILang("Save changes");
        openUploadPic(this, zIndex, uploadP, selectI, saveC);
    }

    /** 切换 用户上传图片返回  */
    async openPicEnd(openWin: SelectHeadDialog, base64: string): Promise<void> {
        if (base64.length > 500) {
            // this.img_head.skin = base64;
            let temp = await HttpCmd.requestPost("wxgame/player/uploadImg", { base64Str: base64 }, false, false);
            if (temp) {
                GlobalDataManager.headId = temp.imgUrl;
                openWin.playerIcon.headSkin = temp.imgUrl;
                openWin.list_head.selectedIndex = -1;
                console.log(temp.imgUrl);
            }
        }
    }

    onRegister() {
        let createName: string = this.input_name.text;
        createName = createName.trim();

        if (createName == "") {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(25)); //Please enter you name
            return;
        }

        if (GlobalDataManager.playerDto.name !== createName) {
            //改名字
            const gold = GlobalDataManager.getConsumeValue(EnumConsumeType.TYPE_GOLD);
            if (gold < Number(this.tf_nameGold.text)) {
                // NoticeMgr.notice(GameLanguageMgr.getLanguage("You don't have enough gold coins to change your nickname"));//当前在等待战斗中，当前操作暂时不可用
                NoticeMgr.notice(GameLanguageMgr.getError(51)); //暂未开放
                return;
            }
        }

        if (GlobalDataManager.headId != -1) {
            this.onModify(createName, GlobalDataManager.headId, GlobalDataManager.countryId);
        } else {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(28)); //Please select a portrait
        }
    }

    async onModify(createName: string, headId: number, countryId: number) {
        // if (createName == "") {
        //     NoticeMgr.notice(GameLanguageMgr.getLanguage(25)); //Please enter you name
        //     return;
        // }
        // let playerDto: PlayerDto = await ETHAccountProxy.updateProfile(createName, headId.toString(), countryId);
        // if (this.destroyed) {
        //     return;
        // }
        // if (playerDto) {
        //     GlobalDataManager.playerDto = playerDto;
        //     this.close();
        //     Signal.event(GameEvent.ROLE_INFO_CHANGE);
        // } else {
        //     NoticeMgr.notice(GameLanguageMgr.getLanguage(29)); //error
        // }
    }
}
