    /**
     * 开始ping测试主服务器延迟
     * 1. 测试主服务器延迟
     * 2. 发送延迟事件更新NetDelaySign组件显示
     * 3. 如果节点列表可见，则更新所有节点延迟
     */
    private startPing(force: boolean = false) {
        // return;
        // 使用最低优先级定时器延迟执行ping操作
        // 给予其他资源加载足够时间完成
        const delayTime = force ? 1000 : 2000; // 非强制时使用更长的延迟

        // setTimeout(() => {
        // 进一步使用requestIdleCallback(如果浏览器支持)或requestAnimationFrame
        // 确保在浏览器空闲时执行
        if (window.requestIdleCallback) {
            window.requestIdleCallback(() => this.executePing(force), { timeout: 100 });
        } else {
            // 降级使用requestAnimationFrame并等待几帧
            let frameCount = 0;
            const waitFrames = (callback: Function) => {
                requestAnimationFrame(() => {
                    if (++frameCount >= 3) {
                        // 等待3帧后执行
                        callback();
                    } else {
                        waitFrames(callback);
                    }
                });
            };
            waitFrames(() => this.executePing(force));
        }
        // }, delayTime);
    }

