    /**
     * 中断所有正在进行的ping测试操作
     * 在需要优先保证用户界面响应时调用
     */
    abortAllPingTests(): void {
        // 设置中断标志
        this.shouldAbortPing = true;

        var nodeMap = SheetDataManager.m_dicNodes.getMap();
        for (const [nodeId, nodeItem] of nodeMap) {
            nodeItem.abort();
        }

        // 1秒后重置中断标志，允许新的ping测试
        setTimeout(() => {
            this.shouldAbortPing = false;
        }, 1000);
    }

    getBestNode() {
        var minNodeItem: NodeItem;
        var nodeMap = SheetDataManager.m_dicNodes.getMap();
        for (const [nodeId, nodeItem] of nodeMap) {
            if (!minNodeItem) {
                minNodeItem = nodeItem;
            } else {
                if (nodeItem.dT != -1 && nodeItem.dT < minNodeItem.dT) {
                    minNodeItem = nodeItem;
                }
            }
        }

        if (minNodeItem) {
            GlobalDataManager.nodeItem = minNodeItem;
            // GlobalDataManager.currentNodeUrl = minNodeItem.url;
        }
    }

