    getNodePoint() {
        //通过当前nodeid
        let point = "1_00";
        const currentNodeItem = GlobalDataManager.nodeItem;
        // let nodeData = SheetDataManager.getNodeByType(currentNodeId);
        if (currentNodeItem) {
            point = currentNodeItem.point;
        }
        return point;
    }

    getWsUrlByRoomNo(roomNo: string): string {
        // 获取房间号
        const point = this.getPointByRoomNo(roomNo);
        // 通过point获取nodeItem
        const nodeItem = SheetDataManager.getNodeIdByPoint(point);
        var socketUrl: string;

        // 获取nodeitem的url
        if (nodeItem) socketUrl = nodeItem.socketUrl;
        return socketUrl;
    }

    getPointByRoomNo(roomNo: string): string {
        // 查找第一个下划线的位置
        const firstIndex = roomNo.indexOf("_");
        if (firstIndex === -1) return roomNo; // 如果没有下划线，返回整个字符串

        // 从第一个下划线后开始查找第二个下划线
        const secondIndex = roomNo.indexOf("_", firstIndex + 1);

        // 返回第二个下划线之前的内容
        return secondIndex === -1
            ? roomNo // 如果找不到第二个下划线，返回整个字符串
            : roomNo.substring(0, secondIndex);
    }
